VALUES ('npc-standing-committee', '全国人大常委会', ARRAY['人大常委会','全国人民代表大会常务委员会'], NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['机构'], '1975年1月17日四届全国人大一次会议修宪废除国家主席，改由全国人民代表大会常务委员会集体行使国家元首职权，至1983年6月18日六届全国人大一次会议选举李先念为国家主席。期间委员长为朱德（1975–1976）、叶剑英（1978–1983）；朱德逝世至叶剑英就任之间由宋庆龄等副委员长集体代理。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/全国人民代表大会常务委员会"}]'::jsonb, NULL, NULL, '全国人大常委会')
